css:
/* ใบเสร็จรับเงิน — unified structural style aligned with Sales Invoice */

@font-face {
    font-family: "TH Sarabun Document";
    src: url("/assets/connect_diagnostics_core/fonts/THSarabun.ttf") format("truetype");
    font-style: normal;
    font-weight: 400 700;
    font-display: block;
}

@page {
    size: 210mm 297mm;
    margin: 0;
}

html,
body {
    margin: 0 !important;
    padding: 0 !important;
}

.print-format {
    width: 210mm !important;
    min-height: 297mm !important;
    margin: 0 !important;
    padding: 0 !important;
}

.cd-receipt.cd-receipt {
    --cd-font: "TH Sarabun Document", "TH SarabunPSK", "Noto Sans Thai", sans-serif;
    --cd-ink: #202020;
    --cd-muted: #666;
    --cd-border: #171717;
    --cd-rule-w: 0.215mm;
    --cd-rule: var(--cd-rule-w) solid var(--cd-border);
    --cd-radius: 3.20mm;

    --cd-fs-base: 4.10mm;
    --cd-fs-value: 4.40mm;
    --cd-fs-label: 3.85mm;
    --cd-fs-en: 2.40mm;
    --cd-fs-company: 7.00mm;
    --cd-fs-company-line: 4.60mm;
    --cd-fs-doc-title: 6.30mm;
    --cd-fs-copy: 5.00mm;
    --cd-fs-money: 4.10mm;
    --cd-fs-total: 4.90mm;

    --cd-lh-field: 6.20mm;
    --cd-lh-address: 5.00mm;

    --cd-page-x: 14.40mm;
    --cd-page-w: 188.56mm;

    --cd-info-top: 55.78mm;
    --cd-info-h: 37.60mm;
    --cd-customer-w: 99.00mm;
    --cd-info-gap: 1.50mm;
    --cd-receipt-w: calc(var(--cd-page-w) - var(--cd-customer-w) - var(--cd-info-gap));

    --cd-grid-top: 95.00mm;
    --cd-grid-h: 138.20mm;

    --cd-footer-top: 234.80mm;
    --cd-footer-h: 53.00mm;

    box-sizing: border-box;
    position: relative;
    width: 210mm;
    min-width: 210mm;
    max-width: 210mm;
    height: 297mm;
    min-height: 297mm;
    max-height: 297mm;
    margin: 0;
    overflow: hidden;
    color: var(--cd-ink);
    background: #fff;
    font-family: var(--cd-font) !important;
    font-size: var(--cd-fs-base) !important;
    font-weight: 400;
    line-height: 1;
    break-after: page;
    page-break-after: always;
    -webkit-print-color-adjust: exact;
    print-color-adjust: exact;
}

.cd-receipt.cd-receipt * {
    box-sizing: border-box;
    font-family: inherit !important;
}

.cd-receipt.cd-receipt.last-page {
    break-after: auto;
    page-break-after: auto;
}

.cd-receipt .th {
    display: block;
    font-size: var(--cd-fs-label);
    line-height: 3.70mm;
}

.cd-receipt .en {
    display: block;
    margin-top: .10mm;
    color: var(--cd-muted);
    font-size: var(--cd-fs-en);
    font-weight: 400;
    line-height: 2.40mm;
}

.cd-receipt .cd-corporate-header {
    position: absolute;
    left: 0;
    top: 0;
    width: 210mm;
    height: 52.30mm;
}

.cd-receipt .cd-corporate-header > div,
.cd-receipt .cd-corporate-header > img {
    position: absolute;
    margin: 0;
    white-space: nowrap;
}

.cd-receipt .company-logo {
    left: 12.70mm;
    top: 18.99mm;
    width: 20.39mm;
    height: 7.78mm;
    object-fit: contain;
}

.cd-receipt .company-name {
    left: 35.88mm;
    top: 13.49mm;
    font-size: var(--cd-fs-company);
    line-height: 7.40mm;
}

.cd-receipt .company-address {
    left: 35.88mm;
    top: 22.35mm;
    font-size: var(--cd-fs-company-line);
    line-height: 5.20mm;
}

.cd-receipt .company-contact {
    left: 35.88mm;
    top: 28.76mm;
    font-size: var(--cd-fs-company-line);
    line-height: 5.20mm;
}

.cd-receipt .company-tax-label,
.cd-receipt .company-tax-value,
.cd-receipt .company-branch {
    top: 36.21mm;
    font-size: var(--cd-fs-label);
    line-height: 4.40mm;
}

.cd-receipt .company-tax-label {
    left: 35.95mm;
}

.cd-receipt .company-tax-value {
    left: 78.45mm;
}

.cd-receipt .company-branch {
    left: 105.00mm;
}

.cd-receipt .document-title {
    left: 133.91mm;
    top: 34.81mm;
    width: 69.75mm;
    height: 9.00mm;
    padding-top: .60mm;
    border-radius: 6mm;
    background: #9fc2e8;
    font-size: var(--cd-fs-doc-title);
    font-weight: 700;
    line-height: 7.80mm;
    text-align: center;
}

.cd-receipt .copy-title {
    left: 141.00mm;
    top: 46.50mm;
    width: 53.40mm;
    font-size: var(--cd-fs-copy);
    font-weight: 700;
    line-height: 6.00mm;
    text-align: center;
}

.cd-receipt .info-box {
    position: absolute;
    top: var(--cd-info-top);
    height: var(--cd-info-h);
    padding: 2.00mm 3.20mm;
    display: flex;
    flex-direction: column;
    overflow: hidden;
    border: var(--cd-rule);
    border-radius: var(--cd-radius);
}

.cd-receipt .customer-box {
    left: var(--cd-page-x);
    width: var(--cd-customer-w);
}

.cd-receipt .receipt-box {
    left: calc(var(--cd-page-x) + var(--cd-customer-w) + var(--cd-info-gap));
    width: var(--cd-receipt-w);
}

.cd-receipt .field-table {
    width: 100%;
    border-collapse: collapse;
    table-layout: fixed;
}

.cd-receipt .field-table td {
    height: var(--cd-lh-field);
    padding: 0 !important;
    border: 0;
    vertical-align: middle;
}

.cd-receipt .field-label {
    width: 24.00mm;
    padding-right: 1.40mm !important;
    font-weight: 400;
}

.cd-receipt .field-value {
    font-size: var(--cd-fs-value);
}

.cd-receipt .field-value.is-strong {
    font-weight: 700;
}

.cd-receipt .receipt-field-table .field-label {
    width: 27.50mm;
}

.cd-receipt .customer-body {
    flex: 1 1 auto;
    min-height: 0;
    overflow: hidden;
}

.cd-receipt .customer-name {
    font-size: var(--cd-fs-value);
    font-weight: 700;
    line-height: 5.30mm;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.cd-receipt .customer-address {
    max-height: 15.50mm;
    overflow: hidden;
    font-size: 4.15mm;
    font-weight: 700;
    line-height: var(--cd-lh-address);
}

.cd-receipt .tax-row {
    flex: 0 0 6.60mm;
    display: flex;
    align-items: flex-end;
    min-width: 0;
}

.cd-receipt .tax-label {
    flex: 0 0 30.50mm;
}

.cd-receipt .tax-value {
    flex: 1 1 auto;
    min-width: 0;
    padding-bottom: .65mm;
    font-size: 4.05mm;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.cd-receipt .branch-value {
    flex: 0 0 25.00mm;
    padding-bottom: .65mm;
    font-size: 3.80mm;
    text-align: right;
    white-space: nowrap;
}

.cd-receipt .field-spacer {
    flex: 1 1 auto;
    min-height: 0;
}

.cd-receipt .receipt-grid {
    position: absolute;
    left: var(--cd-page-x);
    top: var(--cd-grid-top);
    width: var(--cd-page-w);
    height: var(--cd-grid-h);
    overflow: hidden;
    border: var(--cd-rule);
    border-radius: var(--cd-radius) var(--cd-radius) 0 0;
}

.cd-receipt .reference-table {
    width: 100%;
    height: 100%;
    border-collapse: collapse;
    table-layout: fixed;
}

.cd-receipt .reference-table col.col-no { width: 5%; }
.cd-receipt .reference-table col.col-invoice { width: 20%; }
.cd-receipt .reference-table col.col-date { width: 13%; }
.cd-receipt .reference-table col.col-due { width: 13%; }
.cd-receipt .reference-table col.col-amount { width: 16%; }
.cd-receipt .reference-table col.col-remain { width: 17%; }
.cd-receipt .reference-table col.col-paid { width: 16%; }

.cd-receipt .reference-table th,
.cd-receipt .reference-table td {
    padding: 1.25mm 1.80mm !important;
    border: 0;
    border-right: var(--cd-rule);
    overflow: hidden;
}

.cd-receipt .reference-table th:last-child,
.cd-receipt .reference-table td:last-child {
    border-right: 0;
}

.cd-receipt .reference-table thead tr {
    height: 10.40mm;
}

.cd-receipt .reference-table thead th {
    border-bottom: var(--cd-rule);
    text-align: center;
    vertical-align: middle;
    font-weight: 400;
}

.cd-receipt .reference-table tbody {
    height: 113.80mm;
}

.cd-receipt .reference-table tbody tr {
    height: calc(113.80mm / 12);
}

.cd-receipt .reference-table tbody td {
    font-size: 4.05mm;
    line-height: 4.60mm;
    vertical-align: top;
}

.cd-receipt .reference-table .cell-center {
    text-align: center;
}

.cd-receipt .reference-table .cell-money {
    text-align: right;
}

.cd-receipt .reference-table tfoot {
    height: 14.00mm;
}

.cd-receipt .reference-table tfoot tr:first-child {
    height: 8.20mm;
    border-top: var(--cd-rule);
}

.cd-receipt .reference-table tfoot tr:last-child {
    height: 5.80mm;
}

.cd-receipt .amount-words {
    font-size: 4.00mm;
    line-height: 5.00mm;
    vertical-align: middle;
}

.cd-receipt .grand-total-value {
    font-size: var(--cd-fs-total);
    font-weight: 700;
    text-align: right;
    vertical-align: middle;
}

.cd-receipt .grand-total-label-row td {
    border-top: var(--cd-rule);
}

.cd-receipt .grand-total-label {
    padding-right: 3.00mm !important;
    text-align: right;
    vertical-align: middle;
}

.cd-receipt .payment-footer {
    position: absolute;
    left: var(--cd-page-x);
    top: var(--cd-footer-top);
    width: var(--cd-page-w);
    height: var(--cd-footer-h);
    display: flex;
    overflow: hidden;
    border: var(--cd-rule);
    border-radius: 0 0 var(--cd-radius) var(--cd-radius);
}

.cd-receipt .payment-pane,
.cd-receipt .authorization-pane {
    min-width: 0;
    padding: 2.60mm 3.00mm;
}

.cd-receipt .payment-pane {
    flex: 0 0 66%;
    position: relative;
    border-right: var(--cd-rule);
}

.cd-receipt .authorization-pane {
    flex: 0 0 34%;
    position: relative;
}

.cd-receipt .receipt-note {
    height: 5.80mm;
    overflow: hidden;
    font-size: 2.45mm;
    line-height: 2.90mm;
}

.cd-receipt .payment-method-row {
    height: 7.40mm;
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 7.00mm;
}

.cd-receipt .payment-heading {
    font-size: 4.60mm;
    font-weight: 700;
}

.cd-receipt .payment-option {
    font-size: 3.85mm;
}

.cd-receipt .payment-details {
    padding: .50mm 4.00mm 0 18.00mm;
}

.cd-receipt .payment-detail-row {
    min-height: 5.00mm;
    display: flex;
    align-items: center;
    gap: 1.20mm;
    font-size: 3.70mm;
}

.cd-receipt .detail-label {
    flex: 0 0 19.00mm;
    white-space: nowrap;
}

.cd-receipt .detail-label.small-label {
    flex-basis: 9.00mm;
}

.cd-receipt .detail-line {
    flex: 1 1 auto;
    min-width: 0;
    height: 4.20mm;
    padding: 0 .80mm;
    border-bottom: .159mm solid #565656;
    font-size: 3.65mm;
    line-height: 4.10mm;
    white-space: nowrap;
    overflow: hidden;
}

.cd-receipt .detail-line.short-line {
    flex: 0 0 22.00mm;
}

.cd-receipt .collector-area {
    position: absolute;
    left: 3.00mm;
    right: 3.00mm;
    bottom: 1.80mm;
    height: 13.00mm;
    display: flex;
    justify-content: flex-end;
    gap: 2.00mm;
}

.cd-receipt .collector-signature {
    flex: 0 0 52.00mm;
}

.cd-receipt .collector-date {
    flex: 0 0 22.00mm;
}

.cd-receipt .signature-block {
    height: 100%;
    display: flex;
    flex-direction: column;
    justify-content: flex-end;
}

.cd-receipt .signature-line {
    height: 7.20mm;
    border-bottom: .159mm solid #565656;
    display: flex;
    align-items: flex-end;
    justify-content: center;
}

.cd-receipt .signature-caption {
    min-height: 4.60mm;
    padding-top: .60mm;
    overflow: hidden;
    font-size: 3.25mm;
    line-height: 3.70mm;
    text-align: center;
    white-space: nowrap;
}

.cd-receipt .action-name {
    margin-right: .80mm;
}

.cd-receipt .signature-role {
    white-space: nowrap;
}

.cd-receipt .action-signature-image {
    display: block;
    max-width: 38.00mm;
    max-height: 8.00mm;
    object-fit: contain;
}

.cd-receipt .collector-date {
    display: flex;
    flex-direction: column;
    justify-content: flex-end;
}

.cd-receipt .date-value {
    height: 7.20mm;
    border-bottom: .159mm solid #565656;
    display: flex;
    align-items: flex-end;
    justify-content: center;
    font-size: 3.25mm;
}

.cd-receipt .date-label {
    min-height: 4.60mm;
    padding-top: .60mm;
    font-size: 3.25mm;
    line-height: 3.70mm;
    text-align: center;
}

.cd-receipt .approval-head {
    height: 11.00mm;
    text-align: center;
}

.cd-receipt .on-behalf {
    font-size: 3.20mm;
    line-height: 3.80mm;
}

.cd-receipt .signature-company {
    margin-top: .50mm;
    font-size: 4.40mm;
    font-weight: 700;
    line-height: 5.00mm;
}

.cd-receipt .authorized-area {
    height: 18.00mm;
    padding: 0 5.00mm;
}

.cd-receipt .prepared-area {
    position: absolute;
    left: 4.00mm;
    right: 4.00mm;
    bottom: 3.00mm;
}

.cd-receipt .prepared-meta {
    display: flex;
    align-items: baseline;
    justify-content: space-between;
    gap: 2.00mm;
    font-size: 3.20mm;
    line-height: 3.80mm;
    white-space: nowrap;
}

.cd-receipt .prepared-name {
    flex: 1 1 auto;
    overflow: hidden;
    text-overflow: ellipsis;
}

.cd-receipt .prepared-date,
.cd-receipt .prepared-time {
    flex: 0 0 auto;
}

.cd-receipt .prepared-line {
    margin-top: 1.10mm;
    border-bottom: .159mm solid #565656;
}

.cd-receipt .prepared-caption {
    padding-top: .70mm;
    font-size: 3.25mm;
    line-height: 3.80mm;
    text-align: center;
}

.cd-receipt .page-meta {
    position: absolute;
    right: 1.60mm;
    bottom: 1.20mm;
    font-size: 2.80mm;
}
